pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 t, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        (uint unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
